-- Embedded Better Auth issuer for self-hosting (server/src/issuer.ts): users, sessions, keys and
-- OAuth/OIDC provider state, prefixed `auth_`. Generated by better-auth 1.7.7 `getMigrations(...)
-- .compileMigrations()` (the `npx auth generate` builder) against an empty MySQL 8.4 database with
-- createIssuer's options, then reviewed; one object per statement. Better Auth owns these rows;
-- Sanctum tables never reference them. Empty and unused while SANCTUM_EMBEDDED_ISSUER is unset.

create table `auth_user` (`id` varchar(36) not null primary key, `name` varchar(255) not null, `email` varchar(255) not null unique, `emailVerified` boolean not null, `image` text, `createdAt` timestamp(3) default CURRENT_TIMESTAMP(3) not null, `updatedAt` timestamp(3) default CURRENT_TIMESTAMP(3) not null);
create table `auth_session` (`id` varchar(36) not null primary key, `expiresAt` timestamp(3) not null, `token` varchar(255) not null unique, `createdAt` timestamp(3) default CURRENT_TIMESTAMP(3) not null, `updatedAt` timestamp(3) not null, `ipAddress` text, `userAgent` text, `userId` varchar(36) not null references `auth_user` (`id`) on delete cascade);
create table `auth_account` (`id` varchar(36) not null primary key, `accountId` text not null, `providerId` text not null, `userId` varchar(36) not null references `auth_user` (`id`) on delete cascade, `accessToken` text, `refreshToken` text, `idToken` text, `accessTokenExpiresAt` timestamp(3), `refreshTokenExpiresAt` timestamp(3), `scope` text, `password` text, `createdAt` timestamp(3) default CURRENT_TIMESTAMP(3) not null, `updatedAt` timestamp(3) not null);
create table `auth_verification` (`id` varchar(36) not null primary key, `identifier` varchar(255) not null, `value` text not null, `expiresAt` timestamp(3) not null, `createdAt` timestamp(3) default CURRENT_TIMESTAMP(3) not null, `updatedAt` timestamp(3) default CURRENT_TIMESTAMP(3) not null);
create table `auth_jwks` (`id` varchar(36) not null primary key, `publicKey` text not null, `privateKey` text not null, `createdAt` timestamp(3) not null, `expiresAt` timestamp(3), `alg` text, `crv` text);
create table `auth_oauth_client` (`id` varchar(36) not null primary key, `clientId` varchar(255) not null unique, `clientSecret` text, `clientDiscoveryId` text, `disabled` boolean, `skipConsent` boolean, `enableEndSession` boolean, `subjectType` text, `scopes` json, `clientCredentialsScopes` json, `userId` varchar(36) references `auth_user` (`id`) on delete cascade, `createdAt` timestamp(3), `updatedAt` timestamp(3), `name` text, `uri` text, `icon` text, `contacts` json, `tos` text, `policy` text, `softwareId` text, `softwareVersion` text, `softwareStatement` text, `redirectUris` json not null, `postLogoutRedirectUris` json, `backchannelLogoutUri` text, `backchannelLogoutSessionRequired` boolean, `tokenEndpointAuthMethod` text, `applicationType` text, `jwks` text, `jwksUri` text, `grantTypes` json, `responseTypes` json, `requirePKCE` boolean, `dpopBoundAccessTokens` boolean, `referenceId` text, `metadata` json);
create table `auth_oauth_resource` (`id` varchar(36) not null primary key, `identifier` varchar(255) not null unique, `name` text not null, `accessTokenTtl` integer, `refreshTokenTtl` integer, `signingAlgorithm` text, `signingKeyId` text, `allowedScopes` json, `customClaims` json, `dpopBoundAccessTokensRequired` boolean, `disabled` boolean, `createdAt` timestamp(3), `updatedAt` timestamp(3), `policyVersion` integer, `metadata` json);
create table `auth_oauth_client_resource` (`id` varchar(36) not null primary key, `clientId` varchar(191) not null references `auth_oauth_client` (`clientId`) on delete cascade, `resourceId` varchar(191) not null references `auth_oauth_resource` (`identifier`) on delete cascade, `metadata` json, `createdAt` timestamp(3));
create table `auth_oauth_refresh_token` (`id` varchar(36) not null primary key, `token` varchar(255) not null unique, `clientId` varchar(36) not null references `auth_oauth_client` (`clientId`) on delete cascade, `sessionId` varchar(36) references `auth_session` (`id`) on delete set null, `userId` varchar(36) not null references `auth_user` (`id`) on delete cascade, `referenceId` text, `authorizationCodeId` varchar(255), `resources` json, `requestedUserInfoClaims` json, `expiresAt` timestamp(3) not null, `createdAt` timestamp(3) not null, `revoked` timestamp(3), `rotatedAt` timestamp(3), `rotationReplayResponse` text, `rotationReplayExpiresAt` timestamp(3), `authTime` timestamp(3), `confirmation` json, `scopes` json not null);
create table `auth_oauth_access_token` (`id` varchar(36) not null primary key, `token` varchar(255) not null unique, `clientId` varchar(36) not null references `auth_oauth_client` (`clientId`) on delete cascade, `sessionId` varchar(36) references `auth_session` (`id`) on delete set null, `userId` varchar(36) references `auth_user` (`id`) on delete cascade, `referenceId` text, `authorizationCodeId` varchar(255), `resources` json, `requestedUserInfoClaims` json, `refreshId` varchar(36) references `auth_oauth_refresh_token` (`id`) on delete cascade, `expiresAt` timestamp(3) not null, `createdAt` timestamp(3) not null, `revoked` timestamp(3), `confirmation` json, `scopes` json not null);
create table `auth_oauth_consent` (`id` varchar(36) not null primary key, `clientId` varchar(36) not null references `auth_oauth_client` (`clientId`) on delete cascade, `userId` varchar(36) references `auth_user` (`id`) on delete cascade, `referenceId` text, `resources` json, `requestedUserInfoClaims` json, `scopes` json not null, `createdAt` timestamp(3) not null, `updatedAt` timestamp(3) not null);
create table `auth_oauth_client_assertion` (`id` varchar(36) not null primary key, `expiresAt` timestamp(3) not null);
